  if (!toast) return;
  toast.classList.remove('show', 'error', 'loading', 'top-loading');
  if (window.__bankTrackerLargeToastTimer) {
    clearTimeout(window.__bankTrackerLargeToastTimer);
    window.__bankTrackerLargeToastTimer = null;
  }
